 let stageProgress=run.stageTime/360;rect(0,H-3,W,3,'#111523');rect(0,H-3,W*stageProgress,3,stageColors[run.stage][2]);if(run.stageTime<2&&run.time>1){ctx.fillStyle='#fff';ctx.globalAlpha=clamp(1-run.stageTime/2,0,1)*.12;ctx.fillRect(0,18,W,H-18);ctx.globalAlpha=1}}
